/* Display-only first-jab swing replacement. Stages 2/3 delegated unchanged. Mirrors central sprite origin correction.
 * Native combat reach/hits unchanged. World coordinates. */
(()=>{const mods=window.ArenaCharacterModules;for(const id of ['minimax','glm','qwen']){const role=mods?.[id];if(!role)throw new Error('Missing character module '+id);const previous=role.drawEffect;role.drawEffect=function(c,e,env){if(e.kind!=='swing'||e.characterId!==id||e.stage!==1)return previous?.(c,e,env)??false;const u=Math.max(0,Math.min(1,env.u??1-e.life/e.max)),dir=e.dir||1,heavy=e.stage===3,reach=heavy?83:66,raise=e.stage===1?({minimax:90,glm:93,qwen:83}[id]):55;c.save();c.translate(e.x+dir*14,e.y-raise);c.scale(dir,1);c.globalAlpha=1-u;c.lineWidth=1.5;c.beginPath();c.rect(0,-45,reach,90);c.clip();
if(id==='glm'){for(let j=0;j<3;j++){c.save();c.translate(14+u*(reach-27)+j*5,-21+j*18);c.rotate((j-1)*.25+u*.15);c.strokeStyle='#ebd9af';c.fillStyle='rgba(26,28,36,.4)';c.fillRect(-4,-8,8,16);c.strokeRect(-4,-8,8,16);c.beginPath();c.moveTo(-2,-4);c.lineTo(2,-4);c.moveTo(-2,0);c.lineTo(2,0);c.stroke();c.restore();}}
else if(id==='minimax'){c.strokeStyle='#ffd29c';for(let j=0;j<4;j++){const x=10+j*10+u*(reach-45),r=(heavy?20:13)*(1-j*.14);c.beginPath();c.moveTo(x,-r);c.bezierCurveTo(x+8,-r*.4,x+8,r*.4,x,r);c.stroke();}}
else {c.strokeStyle='#d1c3ff';for(let j=0;j<3;j++){const x=12+u*(reach-24);c.beginPath();c.moveTo(3,-18+j*16);c.quadraticCurveTo(x*.6,-26+j*17,x,-16+j*16);c.stroke();}const x=12+u*(reach-24);c.save();c.translate(x,0);c.rotate(-.25+u*.4);c.fillStyle='rgba(185,168,255,.14)';c.beginPath();c.moveTo(0,0);c.arc(0,0,18,-1.1,1.1);c.closePath();c.fill();c.stroke();for(let j=0;j<4;j++){let a=-1.1+j*2.2/3;c.beginPath();c.moveTo(0,0);c.lineTo(Math.cos(a)*18,Math.sin(a)*18);c.stroke();}c.restore();}c.restore();return true;};}})();
